class SourceEvidence(_Strict):
    reference: Text
    description: Text
    sha256: Digest | None

    @field_validator("reference", "description")
    @classmethod
    def nonblank(cls, value):
        if not value.strip():
            raise ValueError("nonblank retained source evidence required")
        return value

